import{_ as t,o,c as d,a2 as r}from"./chunks/framework.DY3PNiwX.js";const p=JSON.parse('{"title":"Upgrading","description":"Migrate an Express merchant off facilitator-owned configuration.","frontmatter":{"description":"Migrate an Express merchant off facilitator-owned configuration."},"headers":[],"relativePath":"upgrading.md","filePath":"upgrading.md"}'),a={name:"upgrading.md"};function c(s,e,i,n,h,l){return o(),d("div",null,[...e[0]||(e[0]=[r('<h1 id="upgrading" tabindex="-1">Upgrading <a class="header-anchor" href="#upgrading" aria-label="Permalink to &quot;Upgrading&quot;">​</a></h1><p><code>@chainsafe/x402-express</code> no longer accepts configuration whose source of truth is the facilitator. The instrument registry admin, the synchronizer, and the relaying <code>feePayer</code> are read from <code>GET /v2/supported</code> on every quote. Discovery is cached by <code>FacilitatorClient</code> (<code>supportedTtlMs</code>, default 5 minutes).</p><h2 id="delete-these-from-a-requirements-spec" tabindex="-1">Delete these from a requirements spec <a class="header-anchor" href="#delete-these-from-a-requirements-spec" aria-label="Permalink to &quot;Delete these from a requirements spec&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Before</th><th>After</th></tr></thead><tbody><tr><td><code>synchronizerId</code></td><td>Remove it. The quote uses <code>extra.synchronizerId</code> from <code>/v2/supported</code>.</td></tr><tr><td><code>feePayer</code></td><td>Remove it. The quote uses the advertised party. There is no merchant fallback.</td></tr><tr><td><code>asset: { instrumentId: { id, admin } }</code></td><td><code>asset: &quot;Amulet&quot;</code> or <code>asset: &quot;USDCx&quot;</code>. The admin comes from <code>/v2/supported</code>.</td></tr><tr><td><code>network</code> used to skip discovery</td><td><code>network</code> only chooses which advertised deployment to quote. Discovery still runs.</td></tr></tbody></table><p><code>payTo</code>, <code>amount</code>, <code>resource</code>, <code>description</code>, <code>maxTimeoutSeconds</code>, <code>executeBeforeSeconds</code>, and <code>memo</code> stay merchant-owned.</p><h2 id="what-fails-closed" tabindex="-1">What fails closed <a class="header-anchor" href="#what-fails-closed" aria-label="Permalink to &quot;What fails closed&quot;">​</a></h2><ul><li>A deployment that advertises no <code>feePayer</code> cannot be quoted. That way to pay is dropped and reported through <code>onQuoteError</code>. It is a facilitator fault, not a <code>TermsError</code>. Other ways to pay on the same route still quote.</li><li>If the named instrument is settled on more than one network, <code>network</code> is required. The middleware does not guess.</li><li>A builder writes the whole of <code>extra</code>, so its <code>instrumentId</code>, <code>synchronizerId</code>, and <code>feePayer</code> are compared with <code>/v2/supported</code> before the 402 is issued. A mismatch is a <code>TermsError</code>.</li></ul><p>A requirements object with no <code>feePayer</code> still fails to parse as canton-exact on the wire. The merchant no longer supplies that field. The middleware copies the one the facilitator advertised.</p>',8)])])}const m=t(a,[["render",c]]);export{p as __pageData,m as default};
